B.XA=new A.Y(B.r,["Ei, {r}! Me tira daqui! Meu canh\xe3o t\xe1 doido pra explodir essa c\xe1psula!","Hey, {r}! Get me out! My cannon is dying to blast this capsule!","\xa1Oye, {r}! \xa1S\xe1came de aqu\xed! \xa1Mi ca\xf1\xf3n se muere por volar esta c\xe1psula!"],t.w)
B.Xk=new A.Y(B.r,["{r}?! Ufa, finalmente! R\xe1pido, antes que os rob\xf4s voltem... eu ouvi eles!","{r}?! Phew, finally! Hurry, before the robots come back... I heard them!","\xbf\xa1{r}!? \xa1Uf, por fin! R\xe1pido, antes de que vuelvan los robots... \xa1los o\xed!"],t.w)
B.WX=new A.Y(B.r,["{r}... senti sua energia. Essa c\xe1psula bloqueia meus poderes. Preciso de voc\xea.","{r}... I felt your energy. This capsule blocks my powers. I need you.","{r}... sent\xed tu energ\xeda. Esta c\xe1psula bloquea mis poderes. Te necesito."],t.w)
B.WC=new A.Y(B.iZ,[B.XH,B.XA,B.Xk,B.WX],t.vb)
B.iT=new A.Y(B.iZ,[2,3,5,8],t.eL)
B.Xx=new A.Y(B.r,["Livre! Valeu, Kael! Agora ningu\xe9m me segura... bora atr\xe1s desses chefes!","Free! Thanks, Kael! Now nobody can stop me... let's go after those bosses!","\xa1Libre! \xa1Gracias, Kael! Ahora nadie me detiene... \xa1vamos por esos jefes!"],t.w)
B.WV=new A.Y(B.r,["At\xe9 que enfim! Agora sim... BUM! Bora derrubar uns chefes!","Finally! Now we're talking... BOOM! Let's take down some bosses!","\xa1Por fin! Ahora s\xed... \xa1BUM! \xa1Vamos a derribar unos jefes!"],t.w)
B.WN=new A.Y(B.r,["Eu avisei que ia dar errado, n\xe3o avisei? Valeu, parceiro. Minha mira \xe9 sua!","I told you it would go wrong, didn't I? Thanks, partner. My aim is yours!","Te dije que saldr\xeda mal, \xbfo no? Gracias, compa\xf1ero. \xa1Mi punter\xeda es tuya!"],t.w)
B.Xw=new A.Y(B.r,["Minha energia voltou... obrigado. Juntos, nada vai nos parar.","My energy is back... thank you. Together, nothing can stop us.","Mi energ\xeda volvi\xf3... gracias. Juntos, nada nos detendr\xe1."],t.w)
B.WD=new A.Y(B.iZ,[B.Xx,B.WV,B.WN,B.Xw],t.vb)
B.XR=new A.Y(B.r,["Segure PULAR na queda para planar!","Hold JUMP while falling to glide!","\xa1Mant\xe9n SALTAR al caer para planear!"],t.w)
B.Xo=new A.Y(B.r,["DASH arrebenta os muros de a\xe7o!","DASH smashes the steel walls!","\xa1DASH rompe los muros de acero!"],t.w)
B.XX=new A.Y(B.r,["O casco de cristal aguenta espinhos!","The crystal hull shrugs off spikes!","\xa1El casco de cristal aguanta las p\xfaas!"],t.w)
B.WE=new A.cL([B.mm,B.XR,B.mk,B.Xo,B.ml,B.XX],A.au("cL<ii,bd<u,u>>"))
